import { Image, View } from '@tarojs/components'
import Taro from '@tarojs/taro'
import { FC } from 'react'
import classNames from 'classnames'
import type { IconProps } from './types'
import { iconPaths } from './paths'
import './index.scss'

export const Icon: FC<IconProps> = ({
  name,
  size = 40,
  color,
  renderMode = 'auto',
  onClick,
  className,
}) => {
  const path = iconPaths[name]
  if (!path) return null

  const env = Taro.getEnv?.()
  const useInlineSvg =
    renderMode === 'svg' || (renderMode === 'auto' && env === Taro.ENV_TYPE?.WEB)
  const isCssVar = typeof color === 'string' && color.startsWith('var(')
  const svgFill = useInlineSvg
    ? color ?? 'currentColor'
    : isCssVar
      ? '#1f2937'
      : color ?? '#1f2937'
  const svgMarkup = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1024 1024"><path fill="${svgFill}" d="${path}"/></svg>`
  const svgDataUri = `data:image/svg+xml;utf8,${encodeURIComponent(svgMarkup)}`

  return (
    <View
      className={classNames('ct-icon', className)}
      style={{ width: `${size}rpx`, height: `${size}rpx`, color }}
      onClick={onClick}
    >
      {useInlineSvg ? (
        <svg viewBox="0 0 1024 1024" fill="currentColor">
          <path d={path} />
        </svg>
      ) : (
        <Image src={svgDataUri} mode="aspectFit" style={{ width: '100%', height: '100%' }} />
      )}
    </View>
  )
}

export default Icon
export type { IconProps, IconName } from './types'
