import { Text, View } from '@tarojs/components'
import Taro from '@tarojs/taro'
import { FC, useEffect, useState } from 'react'
import classNames from 'classnames'
import { OVERLAY_ANIMATION_DURATION } from '../../constants/animation'
import { PickerView } from './PickerView'
import type { PickerOption, PickerProps } from './types'

export const Picker: FC<PickerProps> = ({
  open,
  title,
  confirmText = '确定',
  cancelText = '取消',
  onConfirm,
  onCancel,
  onClose,
  onChange,
  value,
  defaultValue,
  ...pickerViewProps
}) => {
  const [show, setShow] = useState(false)
  const [animating, setAnimating] = useState(false)
  const [tempValue, setTempValue] = useState<(string | number)[]>([])
  const [tempOptions, setTempOptions] = useState<PickerOption[]>([])

  useEffect(() => {
    if (open) {
      setShow(true)
      setTempValue(value ?? defaultValue ?? [])
      Taro.nextTick(() => setAnimating(true))
    } else {
      setAnimating(false)
      const timer = setTimeout(() => setShow(false), OVERLAY_ANIMATION_DURATION)
      return () => clearTimeout(timer)
    }
    return undefined
  }, [open])

  const handlePickerChange = (val: (string | number)[], opts: PickerOption[]) => {
    setTempValue(val)
    setTempOptions(opts)
    onChange?.(val, opts)
  }

  const handleConfirm = () => {
    onConfirm?.(tempValue, tempOptions)
    onClose?.()
  }

  const handleCancel = () => {
    onCancel?.()
    onClose?.()
  }

  if (!show) return null

  return (
    <View className="ct-picker" catchMove>
      <View
        className={classNames('ct-picker__mask', { 'ct-picker__mask--visible': animating })}
        onClick={handleCancel}
      />
      <View
        className={classNames('ct-picker__panel', { 'ct-picker__panel--visible': animating })}
      >
        <View className="ct-picker__toolbar">
          <View className="ct-picker__cancel" onClick={handleCancel}>
            <Text>{cancelText}</Text>
          </View>
          {title && (
            <View className="ct-picker__title">
              <Text>{title}</Text>
            </View>
          )}
          <View className="ct-picker__confirm" onClick={handleConfirm}>
            <Text>{confirmText}</Text>
          </View>
        </View>

        <PickerView {...pickerViewProps} value={tempValue} onChange={handlePickerChange} />
      </View>
    </View>
  )
}

export default Picker
export { PickerView }
export type { PickerProps, PickerViewProps, PickerOption, PickerColumn } from './types'
