import {
  PickerView as TaroPickerView,
  PickerViewColumn,
  Text,
  View,
} from '@tarojs/components'
import { FC, useEffect, useMemo, useState } from 'react'
import classNames from 'classnames'
import type { PickerColumn, PickerOption, PickerViewProps } from './types'

const DEFAULT_ITEM_HEIGHT = 88

export const PickerView: FC<PickerViewProps> = ({
  options,
  columns,
  value,
  defaultValue,
  onChange,
  visibleCount = 5,
  itemHeight = DEFAULT_ITEM_HEIGHT,
  className,
}) => {
  const normalizedColumns = useMemo<PickerColumn[]>(() => {
    if (columns) return columns
    if (options) return [{ options }]
    return []
  }, [columns, options])

  const valueToIndexes = (val?: (string | number)[]) => {
    if (!normalizedColumns.length) return []
    if (!val) return normalizedColumns.map(() => 0)
    return normalizedColumns.map((col, i) => {
      const idx = col.options.findIndex((opt) => opt.value === val[i])
      return idx >= 0 ? idx : 0
    })
  }

  const indexesToValue = (indexes: number[]) => {
    return indexes.map((idx, colIdx) => normalizedColumns[colIdx]?.options[idx]?.value)
  }

  const indexesToOptions = (indexes: number[]) => {
    return indexes.map((idx, colIdx) => normalizedColumns[colIdx]?.options[idx])
  }

  const [selectedIndexes, setSelectedIndexes] = useState(() =>
    valueToIndexes(value ?? defaultValue)
  )

  useEffect(() => {
    if (value !== undefined) {
      setSelectedIndexes(valueToIndexes(value))
    }
  }, [value])

  useEffect(() => {
    if (!normalizedColumns.length) {
      setSelectedIndexes([])
      return
    }
    setSelectedIndexes((prev) =>
      prev.map((idx, colIdx) => {
        const count = normalizedColumns[colIdx]?.options.length ?? 0
        if (count <= 0) return 0
        return Math.min(idx, count - 1)
      })
    )
  }, [normalizedColumns])

  if (!normalizedColumns.length) {
    return (
      <View className={classNames('ct-picker-view', 'ct-picker-view--empty', className)}>
        <Text className="ct-picker-view__empty">暂无数据</Text>
      </View>
    )
  }

  const handleChange = (e: any) => {
    const newIndexes = e.detail.value as number[]
    setSelectedIndexes(newIndexes)
    onChange?.(indexesToValue(newIndexes), indexesToOptions(newIndexes))
  }

  const pickerHeight = itemHeight * visibleCount
  const maskHeight = itemHeight * Math.floor((visibleCount - 1) / 2)

  return (
    <View className={classNames('ct-picker-view', className)}>
      <View
        className="ct-picker-view__mask ct-picker-view__mask--top"
        style={{ height: `${maskHeight}rpx` }}
      />
      <View
        className="ct-picker-view__indicator"
        style={{ height: `${itemHeight}rpx`, top: `${maskHeight}rpx` }}
      />
      <View
        className="ct-picker-view__mask ct-picker-view__mask--bottom"
        style={{ height: `${maskHeight}rpx` }}
      />

      <TaroPickerView
        className="ct-picker-view__wheel"
        style={{ height: `${pickerHeight}rpx` }}
        indicatorStyle={`height: ${itemHeight}rpx`}
        value={selectedIndexes}
        onChange={handleChange}
      >
        {normalizedColumns.map((column, colIdx) => (
          <PickerViewColumn key={colIdx}>
            {column.options.map((option, optIdx) => (
              <View
                key={option.value}
                className={classNames('ct-picker-view__item', {
                  'ct-picker-view__item--selected': optIdx === selectedIndexes[colIdx],
                  'ct-picker-view__item--disabled': option.disabled,
                })}
                style={{ height: `${itemHeight}rpx`, lineHeight: `${itemHeight}rpx` }}
              >
                <Text>{option.label}</Text>
              </View>
            ))}
          </PickerViewColumn>
        ))}
      </TaroPickerView>
    </View>
  )
}
